// TypeScript Version: 4.1

/**
* Result object returned by the resolve function.
*/
interface ResolveResult {
	/**
	* Parent container (object or array). Null for root pointer.
	*/
	target: Record<string, any> | Array<any> | null;

	/**
	* Final reference key. Null for root pointer.
	*/
	key: string | number | null;

	/**
	* Value at the pointer location.
	*/
	value: any;
}

/**
* Resolves a JSON Pointer against a document and returns the target, key, and value.
*
* ## Notes
*
* -   Implements resolution per RFC 6901.
* -   An empty string pointer refers to the root of the document.
* -   The `-` token on the last segment of a pointer targeting an array resolves to the array's length (past-the-end index).
* -   Tokens `__proto__`, `constructor`, and `prototype` are rejected to prevent prototype pollution.
*
* @param document - JSON document
* @param pointer - JSON Pointer string
* @throws first argument must be an object or array
* @throws pointer must resolve to an existing location
* @throws tokens must not be prototype pollution vectors
* @returns result object
*
* @example
* var out = resolve( { 'foo': [ 'bar', 'baz' ] }, '/foo/0' );
* // returns { 'target': [ 'bar', 'baz' ], 'key': 0, 'value': 'bar' }
*
* @example
* var out = resolve( { 'foo': 'bar' }, '/foo' );
* // returns { 'target': { 'foo': 'bar' }, 'key': 'foo', 'value': 'bar' }
*
* @example
* var out = resolve( { 'foo': 'bar' }, '' );
* // returns { 'target': null, 'key': null, 'value': { 'foo': 'bar' } }
*/
declare function resolve( document: Record<string, any> | Array<any>, pointer: string ): ResolveResult;


// EXPORTS //

export = resolve;
